SOURCE=r"""
#define _GNU_SOURCE
#include <dlfcn.h>
#include <stdlib.h>
#include <string.h>
#include <stddef.h>
#include <sys/mman.h>
static int (*next_close)(void *);
static char *(*next_error)(void);
static __thread int armed,pending;
static __thread char *message;
static __thread void *mapping;
static __thread size_t mapped;
static __thread unsigned long closes,errors;
void dl_probe_arm(const void *data, size_t n) {
 if(!next_close)next_close=dlsym(RTLD_NEXT,"dlclose");
 if(!next_error)next_error=dlsym(RTLD_NEXT,"dlerror");
 if(mapping)munmap(mapping,mapped);
 size_t usable=((n+1+4095)/4096)*4096;mapped=usable+4096;
 mapping=mmap(0,mapped,PROT_READ|PROT_WRITE,MAP_PRIVATE|MAP_ANONYMOUS,-1,0);
 if(mapping==MAP_FAILED)abort();
 if(mprotect((char *)mapping+usable,4096,PROT_NONE))abort();
 message=(char *)mapping+usable-(n+1);memcpy(message,data,n);message[n]=0;
 armed=1;pending=0;closes=0;errors=0;
}
void dl_probe_disarm(void){armed=0;pending=0;}
unsigned long dl_probe_count(unsigned long which){return which?errors:closes;}
int dlclose(void *p) {
 if(!next_close)next_close=dlsym(RTLD_NEXT,"dlclose");
 if(armed){armed=0;pending=1;closes++;return -1;}
 return next_close(p);
}
char *dlerror(void) {
 if(pending){pending=0;errors++;return message;}
 if(!next_error)next_error=dlsym(RTLD_NEXT,"dlerror");
 return next_error();
}
"""
cases=[('empty',b''),('ascii',b'actual loader failure'),('emoji',('🙂'*1500).encode()),('long-ASCII',b'A'*7000),('invalid-first',b'\xffx'),('invalid-late',b'A'*5000+b'\xff'),('incomplete',b'a\xe2\x82'),('surrogate',b'\xed\xa0\x80'),('non-BMP',('U🙂界Z'*400).encode()),('all-nonzero-bytes',bytes(range(1,256))*12),('boundary-lead',b'A'*1023+b'\xe2\x82'),('boundary-scalar',b'A'*1023+'🙂tail'.encode()),('page-tail',b'A'*4095),('two-pages-tail',b'\xff'*8191)]
