  for f in fields:rec+=struct.pack('<2Q',at,len(f));tail+=f;at+=len(f)
  rec+=tail;packet=struct.pack('<8s7Q',b'HIAMVSP1',7,len(rec),0,0,0,0,0)+rec
  out=C.create_string_buffer(16384);w=C.create_string_buffer(65536);n=renderer(packet,out,w);assert n<16384;return out.raw[:n]
 def run(item):
