  value=C.create_string_buffer(data);arm(value,len(data));q.reference.attempt();expected=q.reference.native['library']['error'];assert count(0)==count(1)==1
  arm(value,len(data));raw=struct.pack('<8sQQ',b'HIAMVRT3',1,7);s=C.create_string_buffer(raw);out=C.create_string_buffer(768)
  rc=q.ret(s,len(raw),out,768,q.f.work,len(q.f.work));assert rc==0 and out.raw[:8]==b'HIAMVTR3',(name,rc,out.raw[:32].hex())
