  n=get(out,736);text=C.string_at(C.addressof(q.f.work)+(6<<20)+16384,n);actual=text.decode('utf8','surrogatepass')
  assert actual==expected['message'],(name,repr(actual),repr(expected))
  encoded=error_json(text);assert encoded==json.dumps(expected,ensure_ascii=True,separators=(',',':')).encode(),(name,encoded,expected)
  assert native_summary(out)==original_summary(q.reference)
  assert count(0)==count(1)==1
  originaltext=text
  # Free and replace the original TLS error allocation before querying again.
  other=C.create_string_buffer(b'changed loader storage');arm(other,22)
  for magic in (b'HIAMVRT3',b'HIAMVRT2',b'HIAMVRT1'):
   req=struct.pack('<8sQQ',magic,2,7);sb=C.create_string_buffer(req);rc=q.ret(sb,len(req),out,768,q.f.work,len(q.f.work));assert rc==0 and count(0)==count(1)==0
   assert C.string_at(C.addressof(q.f.work)+(6<<20)+16384,n)==originaltext
   if magic==b'HIAMVRT1':assert out.raw[640:]==bytes(128)
   if magic==b'HIAMVRT2':assert out.raw[736:]==bytes(32)
  disarm()
  # This is test teardown of still-open known holders, never a product retry.
  _ctypes.dlclose(q.reference.library._handle);_ctypes.dlclose(get(q.f.work,56))
  os.close(q.reference.identity_pin.fd);os.close(get(q.f.work,32))
  return dict(name=name,input_bytes=len(data),input_sha256=hashlib.sha256(data).hexdigest(),original_error=expected,actual_error_json=encoded.decode(),text_bytes=n,guard_page=True,release_and_dlerror_once=True,captured_text_survives_loader_storage_replacement=True)
 rows=[];before=set(os.listdir('/proc/self/fd'))
